traps.Trap02.txt:
	If ($Event == 1802) @1802;//结局2救蔷薇
	If ($Event == 930) @Label1;
	
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map_036_连接地图.map");
	LoadNpc("map036.npc");
	SaveNpc("temp.npc");
	LoadObj("map036_obj.obj");
	SetPlayerPos(52, 27);
	SetPlayerDir(1);
	EnableNpcAI();
	FadeIn();
	Return;
	
@Label1:
	If ($Result <> 3) @end;
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map_036_连接地图.map");
	LoadNpc("Event94_qiangwei.npc")
	LoadObj("map036_obj.obj");
	SetPlayerPos(52, 27);
	SetPlayerDir(1);
	DisableNpcAI();
	FadeIn();
	SetMapTrap(1, "");
	SetMapTrap(2, "");
	RunScript("事件94.txt");
	Return;
	
@1802:
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	DisableNpcAI();
	LoadMap("map_036_连接地图.map");
	LoadNpc("map036_1.npc");
	LoadObj("map036_obj.obj");
	SetPlayerPos(52,27);
	SetPlayerDir(1);
	FadeIn();
	RunScript("救蔷薇.txt");
	Return;

@end:
	Return;

